AWARD_COLORS = {
    "gold":   ("#DFAE2B", "#A97F12", "Gold Telly Award"),
    "silver": ("#A3ABB4", "#6F7780", "Silver Telly Award"),
    "bronze": ("#B0713A", "#7E4C21", "Bronze Telly Award"),
}

def trophy(kind):
    if kind not in AWARD_COLORS:
        return ""
    fill, edge, label = AWARD_COLORS[kind]
    return (f'<svg class="award-trophy award-trophy--{kind}" viewBox="0 0 24 24" '
            f'role="img" aria-label="{label}"><title>{label}</title>'
            f'<path d="M7 3h10v4.6a5 5 0 0 1-10 0V3z" fill="{fill}" stroke="{edge}" '
            f'stroke-width=".7" stroke-linejoin="round"/>'
            f'<path d="M7 4.6H4.2v1.2A3.8 3.8 0 0 0 7.6 9.6" fill="none" stroke="{fill}" '
            f'stroke-width="1.5" stroke-linecap="round"/>'
            f'<path d="M17 4.6h2.8v1.2A3.8 3.8 0 0 1 16.4 9.6" fill="none" stroke="{fill}" '
            f'stroke-width="1.5" stroke-linecap="round"/>'
            f'<rect x="10.9" y="12.2" width="2.2" height="4" fill="{fill}" stroke="{edge}" stroke-width=".7"/>'
            f'<rect x="7.4" y="16" width="9.2" height="2.6" rx="1.3" fill="{fill}" stroke="{edge}" stroke-width=".7"/>'
            f'</svg>')

# A meeting whose agenda was looked for on CivicClerk and not found, as against
# the 120 older School Committee meetings that never had one at all. Both reach
# nl_episode() with no agenda text, and they must not look the same: the old
# ones show no button, this one shows the button greyed out. Update_SV runs
# unattended, so the two cases have to be told apart without anyone to ask.
AGENDA_PENDING = object()


# Set at the top of a year's listing wherever the descriptions under it were
# written from the videos themselves rather than supplied by whoever made them:
# the School Committee from 2024-25 on, the Civic TV boards from 2026. Frank
# asked for it on 2026-10-25. It goes per year panel rather than once per
# section so it sits with the descriptions it is about and claims nothing about
# the years either side. It lives up here because the Civic TV page is
# assembled thousands of lines before the School Videos one.
AI_NOTE = ("Note: video descriptions are written by Artificial Intelligence "
           "(AI) and AI can make mistakes.")


def nl_episode(vid, title, desc, thumb=None, award=None, agenda=None, rule=False):
    # `vid` is normally an 11-character YouTube id. A full URL is also accepted,
    # for the occasional video hosted somewhere else — the Land & Water
    # Council's 50th anniversary film is on Vimeo. Those have no predictable
    # thumbnail URL, so they must supply a local one in assets/.
    external = "://" in vid
    url = vid if external else f"https://youtu.be/{vid}"
    if external and not thumb:
        raise ValueError("a non-YouTube video needs a local thumbnail: %s" % vid)
    # Thumbnails with no local file fall back to YouTube's. Older uploads have
    # no maxresdefault; initThumbFallback() in site.js swaps those to hqdefault
    # at load time (see the comment there for why onerror cannot do it).
    src = f"assets/{thumb}?v={ASSET_VER}" if thumb else f"https://img.youtube.com/vi/{vid}/maxresdefault.jpg"
    # Outside production companies are credited under the thumbnail; see
    # VIDEO_CREDITS at the top of this file.
    credit = "" if external else VIDEO_CREDITS.get(vid, "")
    # AGENDA_PENDING is not agenda text, so it is taken off `agenda` here and
    # carried separately: every test below reads `agenda` as "there is an
    # agenda to show", which stays true.
    pending = agenda is AGENDA_PENDING
    if pending:
        agenda = None
    # An `agenda` turns on a second pill that swaps the description for the
    # meeting's posted agenda. Both ship in the page; site.js only toggles them.
    agenda_block = (f'\n        <div class="watch-episode__agenda" hidden>{agenda}</div>'
                    if agenda else "")
    watch = (f'<a class="watch-episode__link" href="{url}" target="_blank"'
             f' rel="noopener">Click Here to Watch</a>')
    if agenda or pending:
        # With an agenda there are two pills, so they split up: the watch link
        # goes under the thumbnail and the agenda button takes the spot beneath
        # the description. Cards without an agenda keep the markup they have
        # always had, so nothing else on the site moves.
        if pending:
            # Same words and same slot as a working button, greyed and really
            # disabled rather than merely looking it. It deliberately does not
            # carry .watch-episode__agenda-btn: that is what site.js binds the
            # toggle to, and there is nothing here to toggle.
            agenda_btn = ('<button type="button" class="watch-episode__link '
                          'watch-episode__link--alt watch-episode__agenda-btn--pending" '
                          'disabled aria-label="Meeting Agenda &ndash; not posted yet">'
                          'Meeting Agenda</button>')
        else:
            agenda_btn = ('<button type="button" class="watch-episode__link '
                          'watch-episode__link--alt watch-episode__agenda-btn" '
                          'aria-expanded="false">Meeting Agenda</button>')
        media = ('      <div class="watch-episode__media">\n'
                 f'        <div class="watch-episode__thumb">\n'
                 f'          <img src="{src}" alt="{title}" loading="lazy">\n'
                 f'        </div>\n'
                 f'        <div class="watch-episode__actions">\n'
                 f'          {watch}\n          {agenda_btn}\n'
                 f'        </div>\n      </div>')
        actions = ""
    else:
        # A credited video borrows the agenda layout's media column so the
        # credit can sit under the thumbnail at the same width. Cards with no
        # credit keep the bare thumb div they have always had, so no other
        # card on the site moves.
        if credit:
            media = ('      <div class="watch-episode__media">\n'
                     f'        <div class="watch-episode__thumb">\n'
                     f'          <img src="{src}" alt="{title}" loading="lazy">\n'
                     f'        </div>\n'
                     f'        {credit}\n'
                     '      </div>')
        else:
            media = (f'      <div class="watch-episode__thumb">\n'
                     f'        <img src="{src}" alt="{title}" loading="lazy">\n'
                     f'      </div>')
        actions = "\n        " + watch
    # A card with no description -- the graduations, promotions and the WCPS-era
    # bulletins, which are titled by date and need no summary -- leaves the
    # paragraph out rather than shipping an empty one, whose bottom margin would
    # otherwise hold open a gap under the title. It carries its own leading
    # newline, the way agenda_block and actions do.
    mark = trophy(award)
    desc_block = (f'\n        <p class="watch-episode__desc">{desc}</p>'
                  if desc.strip() else "")
    # The closing hairline is decided by the caller, not here: it depends on the
    # other cards in the same panel. See panel_cards().
    tail = '\n    <hr class="watch-episode__rule">' if rule else ""
    return f"""    <article class="watch-episode" data-reveal>
{media}
      <div class="watch-episode__text">
        <h3 class="watch-episode__title">{title}{mark}</h3>{desc_block}{agenda_block}{actions}
      </div>
    </article>{tail}"""


# Alphabetical order for anything the reader picks from by name: the section
# headings on a nonprofit page and the logo buttons on the Nonprofit Videos
# page. Entities and markup have to come off before two labels can be
# compared: "International Women&rsquo;s Day" and "Nantucket Summer Forum
# <span ...>(co-sponsored ...)</span>" would otherwise sort by their markup.
# Leading punctuation comes off too, so &rsquo;Sconset files under S, which is
# the rule the NHA's Browse lists already follow.
_LABEL_ENTITIES = (("&amp;", "&"), ("&rsquo;", "'"), ("&ndash;", "-"),
                   ("&mdash;", "-"), ("&nbsp;", " "), ("&hellip;", "..."),
                   ("&ldquo;", '"'), ("&rdquo;", '"'))

def label_key(label):
    """Sort key for a partner page's section labels: plain text, case-folded,
    with leading punctuation and a leading "The" ignored, so "The Cranberry
    Bogs" files under C -- Frank, 2026-10-25. Only "The": no section starts
    with "A" or "An", and guessing at articles that are not there would file a
    future section somewhere nobody expects. A label that is only the word
    "The" keeps it, rather than sorting as the empty string."""
    plain = re.sub(r"<[^>]+>", "", label)
    for ent, ch in _LABEL_ENTITIES:
        plain = plain.replace(ent, ch)
    plain = re.sub(r"^[^0-9A-Za-z]+", "", plain)
    return re.sub(r"^the\s+(?=\S)", "", plain, flags=re.I).casefold()

# ----------------------------------------------------------------------
def shell(page_key, title, body, head_extra="", scripts=""):
    return f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{title}</title>
<meta name="description" content="Nantucket Community Television — Vision. Voice. Life. Broadcasting Nantucket on Channels 8 | 1072.">
<link rel="icon" type="image/png" href="assets/favicon.png">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,400;0,9..144,560;0,9..144,700;1,9..144,500&family=Hanken+Grotesk:wght@400;500;600;650;700&family=Space+Mono:wght@400;700&display=swap" rel="stylesheet">
<link rel="stylesheet" href="styles.css?v={ASSET_VER}">{head_extra}
</head>
<body data-page="{page_key}">

<!-- broadcast status strip -->
<div class="status-strip">
  <div class="wrap">
    <span class="live">On Air</span>
    <span class="sep">/</span>
    <span>Nantucket, MA</span>
    <span class="sep">/</span>
    <span>TV Channels: Civic 8 &amp; HD 1072</span>
    <span class="roll">Vision. Voice. Life.</span>
  </div>
</div>

<!-- navigation (built by site.js) -->
<header id="site-nav"></header>

{body}

<!-- footer (built by site.js) -->
<footer id="site-footer"></footer>

<script src="site.js?v={ASSET_VER}"></script>{scripts}
</body>
</html>"""

# ----------------------------------------------------------------------
def page_header(eyebrow, h1, sub, wide_sub=False):
    """`wide_sub` lets the sentence under the title run to a wider measure than
    the 60ch the other pages read better at -- for a one-liner that should sit
    under the heading like a deck rather than start a column of text."""
    cls = ' class="pagehead__sub--wide"' if wide_sub else ''
    return f"""<header class="pagehead">
  <div class="wrap">
    <span class="eyebrow"><span class="dot"></span>{eyebrow}</span>
    <h1>{h1}</h1>
    <p{cls}>{sub}</p>
  </div>
</header>"""

# A single video card. `vid` is the YouTube ID, title/meta are labels.
def video_card(vid, title, meta, idx, title_above=False):
    delay = (idx % 4) + 1
    frame = f"""<div class="video__frame">
          <iframe loading="lazy"
            src="https://www.youtube-nocookie.com/embed/{vid}?rel=0"
            title="{title}"
            allow="accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
            allowfullscreen></iframe>
        </div>"""
    tcls = "video__title video__title--above" if title_above else "video__title"
    title_html = f'<h3 class="{tcls}">{title}</h3>'
    meta_html = f'<p class="video__meta">{meta}</p>'
    inner = (f"{title_html}\n        {frame}\n        {meta_html}"
             if title_above else
             f"{frame}\n        {title_html}\n        {meta_html}")
    return f"""      <!-- ───────── VIDEO {idx+1} · paste a YouTube ID below ───────── -->
      <article class="video" data-reveal data-reveal-d="{delay}">
        {inner}
      </article>"""

def video_page(page_key, title_tag, eyebrow, h1, sub, meta, count, label_prefix, hero=None, first=None, below_hero="", first_above=False, featured=None):
    head = hero if hero else page_header(eyebrow, h1, sub)
    if featured:
        # Single "Featured Video" block as its own full-width section.
        main = f"""<main class="section sport-featured">
  <div class="wrap">
{featured_block(*featured)}
  </div>
</main>"""
    elif count == 0:
        main = ""
    else:
        def _card(i):
            if i == 0 and first:
                return video_card(first[0], first[1], meta, 0, title_above=first_above)
            return video_card(BANNER_ID, f"{label_prefix} {i+1}", meta, i)
        cards = "\n".join(_card(i) for i in range(count))
        edit_note = f"""
<!-- =====================================================================
     HOW TO EDIT THIS PAGE
     Each block below is one video. To feature a real video:
       1. Find its YouTube ID — the part after "watch?v=" or "youtu.be/".
          e.g.  https://youtu.be/4fJ2KRlEKNI   ->  ID is  4fJ2KRlEKNI
       2. Replace the ID in the iframe src (the bit after /embed/ ).
       3. Update the <h3> title and <p class="video__meta"> line.
     To add more videos, copy a whole <article class="video"> ... </article>
     block and paste it in. To remove one, delete its block.
     ===================================================================== -->"""
        main = f"""<main class="section">
  <div class="wrap">{edit_note}
    <div class="videos">
{cards}
    </div>
  </div>
</main>"""
    body = f"""{head}
{below_hero}
{main}"""
    return shell(page_key, title_tag, body)

# ----------------------------------------------------------------------
# Custom channel hero banner: brand gradient + logo on a white card + title.
def channel_hero(modifier, visual, h1, sub, extra="", h1_hidden=False):
    h1cls = "chero__title sr-only" if h1_hidden else "chero__title"
    extra_html = f'\n  <div class="wrap chero__extra">{extra}</div>' if extra else ""
    sub_html = f'\n      <p class="chero__sub">{sub}</p>' if sub else ""
    return f"""<section class="chero chero--{modifier}">
  <div class="wrap chero__inner">
    <span class="chero__card">{visual}</span>
    <div class="chero__text">
      <h1 class="{h1cls}">{h1}</h1>{sub_html}
    </div>
  </div>{extra_html}
</section>"""

def chero_logo(fname, alt):
    return f'<img src="assets/{fname}?v={ASSET_VER}" alt="{alt}">'

