# Video hero banner: full-bleed muted/looped YouTube background with a photo
# fallback, plus title text. Mirrors the home banner mechanism, so a page
# using this should not also carry the home banner script.
def video_hero(vid, fallback, eyebrow="", h1="", sub="", bare=False):
    inner = "" if bare else f"""  <div class="hero__scrim"></div>
  <div class="hero__inner wrap">
    <span class="eyebrow"><span class="dot"></span>{eyebrow}</span>
    <h1 class="vhero__title">{h1}</h1>
    <p class="hero__sub">{sub}</p>
  </div>"""
    cls = "vhero vhero--bare" if bare else "vhero"
    return f"""<section class="{cls}">
  <div class="hero__media">
    <img class="hero__fallback" src="assets/{fallback}" alt="{h1 or 'Nantucket Shorts Fest'}">
    <div class="hero__video" aria-hidden="true"><div id="heroVideo"></div></div>
  </div>
  <div class="hero__shield" aria-hidden="true"></div>
{inner}
</section>
  <script>
  (function(){{
    var HERO_VIDEO_ID = "{vid}";
    if (window.matchMedia && window.matchMedia("(prefers-reduced-motion:reduce)").matches) return;
    var wrap = document.querySelector(".hero__video");
    var media = document.querySelector(".hero__media");
    if (!wrap || !document.getElementById("heroVideo")) return;
    var started = false;
    function show(){{ if (media) media.classList.add("is-playing"); }}
    function hide(){{ if (media) media.classList.remove("is-playing"); }}
    function init(){{
      new YT.Player("heroVideo", {{
        videoId: HERO_VIDEO_ID,
        playerVars: {{
          autoplay:1, mute:1, controls:0, iv_load_policy:3,
          modestbranding:1, rel:0, playsinline:1, disablekb:1, fs:0,
          origin: location.origin
        }},
        events: {{
          onReady: function(e){{ e.target.mute(); e.target.playVideo();
            setTimeout(function(){{ try{{ e.target.playVideo(); }}catch(_){{}} }}, 400);
            setInterval(function(){{ try{{ var d=e.target.getDuration(); if(d>1 && e.target.getCurrentTime()>=d-0.4){{ e.target.seekTo(0,true); }} }}catch(_){{}} }}, 250); }},
          onStateChange: function(e){{
            if (e.data === YT.PlayerState.PLAYING) {{ if (!started) {{ started = true; setTimeout(show, 700); }} }}
            else if (e.data === YT.PlayerState.PAUSED) {{ hide(); }}
            else if (e.data === YT.PlayerState.ENDED) {{ try{{ e.target.seekTo(0,true); e.target.playVideo(); }}catch(_){{}} }}
          }},
          onError: function(){{ hide(); }}
        }}
      }});
    }}
    if (window.YT && window.YT.Player) {{
      init();
    }} else {{
      var prev = window.onYouTubeIframeAPIReady;
      window.onYouTubeIframeAPIReady = function(){{ if (typeof prev === "function") prev(); init(); }};
      if (!document.getElementById("yt-iframe-api")) {{
        var tag = document.createElement("script");
        tag.id = "yt-iframe-api";
        tag.src = "https://www.youtube.com/iframe_api";
        document.head.appendChild(tag);
      }}
    }}
    setTimeout(function(){{ if (!started) hide(); }}, 8000);
  }})();
  </script>"""

