def partner_buttons():
    # Alphabetical, by the same label_key() the section headings use, so a
    # partner added to the list cannot land out of order -- Frank, 2026-10-25.
    # The Community Foundation's fund logos below this grid are sorted the same
    # way, by cfn_funds_section().
    tiles=[]
    for i,(name,logo,page) in enumerate(sorted(PARTNERS, key=lambda p: label_key(p[0]))):
        d=(i%4)+1
        tiles.append(
f'''        <a class="partner" href="{page}" aria-label="{name}" data-reveal data-reveal-d="{d}">
          <img class="partner__logo" src="assets/{logo}?v={ASSET_VER}" alt="{name}">
        </a>''')
    return '<div class="partners">\n'+"\n".join(tiles)+'\n      </div>'

