# 2) ABOUT — STAFF & BOARD
def _esc(s):
    return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")

def initials(name):
    parts=[p for p in name.replace(".","").split() if p]
    if not parts: return "•"
    if len(parts)==1: return parts[0][:2].upper()
    return (parts[0][0]+parts[-1][0]).upper()

def person_card(p, idx):
    d=(idx%4)+1
    name=_esc(p["name"])
    role = f'<div class="person__role">{_esc(p["role"])}</div>' if p.get("role") else ""
    email = (f'<p class="person__email"><a href="mailto:{p["email"]}">{p["email"]}</a></p>'
             if p.get("email") else "")
    bio=""
    if p.get("bio"):
        paras="".join(f"<p>{_esc(par)}</p>" for par in p["bio"])
        bio=(f'<details class="bio">'
             f'<summary><span class="bio__open">Read bio</span>'
             f'<span class="bio__close">Hide bio</span></summary>'
             f'<div class="person__bio">{paras}</div></details>')
    return f"""      <article class="person" data-reveal data-reveal-d="{d}">
        <div class="person__id">
          <div class="person__head">
            <span class="monogram" aria-hidden="true">{initials(p["name"])}</span>
            <div>
              <div class="person__name">{name}</div>
              {role}
            </div>
          </div>
          {email}
        </div>
        {bio}
      </article>"""

