def sponsor_map(banner, lazy=False):
    img, alt, logos = banner
    load = ' loading="lazy"' if lazy else ""
    btns = "\n".join(
        f'      <a class="sponsormap__btn" href="{url}" target="_blank" rel="noopener" '
        f'aria-label="{name}" style="left:{l}%;top:{t}%;width:{round(r - l, 1)}%;'
        f'height:{round(b - t, 1)}%{";border-radius:" + rad if rad else ""}"></a>'
        for name, url, l, t, r, b, rad in logos)
    return f"""<div class="sponsormap">
      <img class="sports-sponsors__img" src="assets/{img}?v={ASSET_VER}" alt="{alt}"{load}>
{btns}
    </div>"""

def sports_sponsors_section():
    return f"""<section class="section sports-sponsors">
  <div class="wrap">
    {sponsor_map(SPONSOR_TOP)}
  </div>
</section>"""

