def shorts_submit_section():
    bullets = [
      "Films must be created on or inspired by the island of Nantucket.",
      "Film length: 2-10 minutes.",
      "Films cannot be a commercial for a local business.",
      "Films must have a beginning, middle, and an end.",
      "Submission fee is $50. Student &amp; first-time filmmakers: $35.",
      "Top films will be selected by a jury and shown at the Dreamland Theater.",
      "All music must have music rights and be appropriately cleared.",
      "Submission format: 1080p /24p/ h.264",
      "Films may be posted online to a pay-per-view link as part of a fundraiser benefitting NCTV. This link will be active for no greater than 1 year.",
      "Films may be shown a few times at the Dreamland during &ldquo;encore&rdquo; presentations of the Shorts Fest.",
      "All films will be shown on NCTV Channel 8 &amp; 1072.",
      "All films will be shown on NCTV's YouTube Channel.",
      "Submissions are due by 5pm on 9/10/27.",
      # Lisa's address is a mailto, the way every other contact address on the
      # site is -- Frank gave it as plain text on 2026-10-25, but a reader
      # should be able to click it. No closing full stop: a period against an
      # address reads as part of it.
      ('Questions? Email the Shorts Fest Director Lisa Getter at '
       '<a href="mailto:lisa@ournctv.org">lisa@ournctv.org</a>'),
    ]
    lis = "\n".join(f"        <li>{b}</li>" for b in bullets)
    return f"""<section class="section shorts-submit">
  <div class="wrap">
    <div class="section__head" data-reveal>
      <span class="eyebrow"><span class="dot"></span>Guidelines</span>
      <h2>How to Submit to the 2027 Shorts Fest</h2>
    </div>
    <div class="criteria" data-reveal>
      <h3>Film Submission Criteria at a Glance:</h3>
      <ul class="criteria__list">
{lis}
      </ul>
    </div>
  </div>
</section>"""

# AWARDS -- two per year, Best New Filmmaker then Audience Choice. Each entry
# is (winning film, image in assets/). The year buttons reuse the lecture-
# archive picker: one year is always open, and the markup opens on AWARDS_OPEN.
AWARDS_OPEN = "2026"
AWARDS = {
 "2023": [("Contemplating by Vivian Crosby",                 "contemplating.webp"),
          ("Lost in Nevers Land by Penny Dey",               "lost-in-nevers-land.webp")],
 "2024": [("Nantucket Cribz by John Eboli",                  "nantucket-cribz.webp"),
          ("Azure Odyssey by Oscar Waldman &amp; Sam Billings", "azure-odyssey.webp")],
 "2025": [("The Meeting Place by Charity Grace Mofsen",      "the-meeting-place.webp"),
          ("Two Nights for a Quarter by Penny Dey",          "two-nights-for-a-quarter.webp")],
 "2026": [("Something Else by Kate Hamilton Pardee",         "something-else.webp"),
          ("The One Star Weekend by Mark Kiefer",            "the-one-star-weekend.webp")],
}

def shorts_awards_section():
    trophy = '<svg class="award__ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 4h10v5a5 5 0 0 1-10 0V4z"/><path d="M7 6H4.6a1.4 1.4 0 0 0 1.6 2.8"/><path d="M17 6h2.4a1.4 1.4 0 0 1-1.6 2.8"/><path d="M12 14v3"/><path d="M9 20h6"/><path d="M9.6 20 10 17"/><path d="M14.4 20 14 17"/></svg>'
    camera = '<svg class="award__ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="7.5" cy="6" r="3"/><circle cx="13" cy="6" r="2.5"/><rect x="3" y="10" width="12.5" height="9" rx="1.6"/><path d="M15.5 12.8 21 10.3v8.4l-5.5-2.5z"/></svg>'
    labels = [(trophy, "Best New Filmmaker Award:"), (camera, "Audience Choice Award:")]
    years = sorted(AWARDS)
    btns = "\n".join(
        f'        <button type="button" class="year-btn{" is-active" if yr == AWARDS_OPEN else ""}" '
        f'data-year="{yr}" aria-pressed="{"true" if yr == AWARDS_OPEN else "false"}">{yr}</button>'
        for yr in years)

    def figures(yr):
        # Every year but the open one starts hidden, so its stills load only
        # once the reader asks for that year.
        lazy = "" if yr == AWARDS_OPEN else ' loading="lazy"'
        return "\n".join(
            f"""          <figure class="award">
            <figcaption class="award__cap"><span class="award__label">{ico}{label}</span><br>{film}</figcaption>
            <img src="assets/{img}?v={ASSET_VER}" alt="{film}"{lazy}>
          </figure>"""
            for (ico, label), (film, img) in zip(labels, AWARDS[yr]))

    panels = "\n".join(
        f"""        <div class="year-panel" data-year="{yr}"{"" if yr == AWARDS_OPEN else " hidden"}>
          <div class="awards-grid">
{figures(yr)}
          </div>
        </div>"""
        for yr in years)

    return f"""<section class="section shorts-awards">
  <div class="wrap">
    <div class="section__head" data-reveal>
      <span class="eyebrow"><span class="dot"></span>Awards</span>
      <h2>Congratulations to our Shorts Fest winners!</h2>
    </div>
    <div class="yearpick" data-reveal>
      <div class="yearpick__btns" role="group" aria-label="Shorts Fest winners by year">
{btns}
      </div>
      <div class="yearpick__panels">
{panels}
      </div>
    </div>
  </div>
</section>"""

