def filmmap_buttons(grid, cols, rows):
    btns = []
    for ci, col in enumerate(grid):
        L, R = cols[ci]
        for ri, (title, url) in enumerate(col):
            if not url:                      # film shown on the poster but not yet linked
                continue
            T, B = rows[ri]
            btns.append(
                f'      <a class="filmmap__btn" href="{url}" target="_blank" rel="noopener" '
                f'aria-label="{title}" style="left:{L}%;top:{T}%;width:{round(R-L,1)}%;height:{round(B-T,1)}%"></a>')
    return "\n".join(btns)

