def webp_size(path):
    """Pixel size of a WebP, read straight from its header.

    The grid's <img> tags need width and height so the browser can reserve the
    right box before the file arrives. Without them a lazy image is 0px tall,
    the masonry column collapses, every photo lands in the viewport at once and
    downloads immediately -- which is the opposite of what loading="lazy" is
    for -- and the page jumps as they fill in. Reading the real file keeps the
    numbers honest; hand-written ones would rot the first time a photo is
    re-exported. Pure stdlib, so build.py still needs nothing installed."""
    with open(path, "rb") as fh:
        head = fh.read(30)
    if head[:4] != b"RIFF" or head[8:12] != b"WEBP":
        return None
    kind = head[12:16]
    if kind == b"VP8 ":                       # simple lossy
        if head[23:26] != b"\x9d\x01\x2a":
            return None
        w = int.from_bytes(head[26:28], "little") & 0x3FFF
        h = int.from_bytes(head[28:30], "little") & 0x3FFF
        return w, h
    if kind == b"VP8L":                       # lossless
        bits = int.from_bytes(head[21:25], "little")
        return (bits & 0x3FFF) + 1, ((bits >> 14) & 0x3FFF) + 1
    if kind == b"VP8X":                       # extended (alpha, metadata)
        w = int.from_bytes(head[24:27], "little") + 1
        h = int.from_bytes(head[27:30], "little") + 1
        return w, h
    return None

# Photo credit per year, as (photographer, where to buy prints). A year with no
# entry simply gets no credit line, so this does not have to be filled in for
# every year that has photos.
SHORTS_PHOTO_CREDITS = {
    "2026": ("Charity Grace Photography", "https://www.charitygracephotography.com/"),
}

def photo_credit(credits, yr):
    """The credit line for a year, or "" when that year has no credit.

    Rendered once above the grid and cloned into the photo viewer by
    initPhotoLightbox(), so the two can never drift apart."""
    if yr not in credits:
        return ""
    who, url = credits[yr]
    return (f'            <p class="photo-credit">Photos by {who}. For prints, '
            f'<a href="{url}" target="_blank" rel="noopener">click here</a>.</p>\n')

def photo_gallery_section(css_class, photos, credits, aria):
    """A year-by-year photo gallery: eyebrow, heading, year buttons, masonry.

    Shared by the Shorts Fest and New Moon Fest galleries so the two cannot
    drift apart. A year with an empty list still gets a button, disabled and
    dashed, so the archive's full span shows. No year is selected on load, so
    the thumbnails sit in a hidden panel with loading="lazy" and a reader who
    never picks a year downloads none of them.

    Every thumbnail carries its real pixel size: without it a lazy image is 0px
    tall, the masonry column collapses, and every photo lands in the viewport
    at once -- the opposite of what lazy loading is for."""
    years = sorted(photos)
    btns = []
    for yr in years:
        if photos[yr]:
            btns.append(f'          <button type="button" class="year-btn" '
                        f'data-year="{yr}" aria-pressed="false">{yr}</button>')
        else:
            btns.append(f'          <button type="button" class="year-btn" disabled '
                        f'title="Photos from the {yr} festival are not online yet">{yr}</button>')

    def grid(yr):
        def item(stem, alt):
            size = webp_size(os.path.join(OUT, "assets", stem + ".webp"))
            dims = f' width="{size[0]}" height="{size[1]}"' if size else ""
            return (f'              <button type="button" class="photo-grid__item" '
                    f'data-full="assets/{stem}-lg.webp?v={ASSET_VER}">\n'
                    f'                <img src="assets/{stem}.webp?v={ASSET_VER}" alt="{alt}"'
                    f'{dims} loading="lazy">\n'
                    f'              </button>')
        items = "\n".join(item(stem, alt) for stem, alt in photos[yr])
        return f'            <div class="photo-grid">\n{items}\n            </div>'

    panels = "\n".join(
        f'          <div class="year-panel" data-year="{yr}" hidden>\n'
        f'{photo_credit(credits, yr)}'
        f'{grid(yr)}\n'
        f'          </div>'
        for yr in years if photos[yr])

    return f"""<section class="section {css_class}">
  <div class="wrap">
    <div class="section__head" data-reveal>
      <span class="eyebrow"><span class="dot"></span>Festival Photos</span>
    </div>
    <div class="dl-group dl-group--static" data-reveal>
      <h2 class="dl-group__title">Select a Year to See Photos from that Festival</h2>
      <div class="dl-group__body">
        <div class="yearpick yearpick--toggle">
          <div class="yearpick__btns" role="group" aria-label="{aria}">
{chr(10).join(btns)}
          </div>
          <div class="yearpick__panels">
{panels}
          </div>
        </div>
      </div>
    </div>
  </div>
</section>"""

def shorts_photos_section():
    return photo_gallery_section("shorts-photos", SHORTS_PHOTOS,
                                 SHORTS_PHOTO_CREDITS, "Festival photos by year")

def shorts_pastfilms_section():
    """The past film maps, one year at a time behind a collapsible heading.

    Years run oldest to newest left to right, like every other picker on the
    site; the page previously listed them newest-first as three static blocks
    that were all on screen at once. No year is selected on load. The clickable regions over each map are
    plain <a> tags with no script behind them, so nothing has to be re-run when
    a panel is shown. Each map carries its real pixel size and loading="lazy":
    an image with no width or height is 0px tall until it loads, which collapses
    the panel it sits in and defeats the lazy loading."""
    years = [
        ("2023", FILM_GRID_2023, FILM_COLS_2023, FILM_ROWS_2023),
        ("2024", FILM_GRID_2024, FILM_COLS_2024, FILM_ROWS_2024),
        ("2025", FILM_GRID_2025, FILM_COLS_2025, FILM_ROWS_2025),
    ]

    btns = "\n".join(
        f'          <button type="button" class="year-btn" data-year="{yr}" '
        f'aria-pressed="false">{yr}</button>'
        for yr, _, _, _ in years)

    def panel(yr, grid, cols, rows):
        size = webp_size(os.path.join(OUT, "assets", f"{yr}-films.webp"))
        dims = f' width="{size[0]}" height="{size[1]}"' if size else ""
        return (f'          <div class="year-panel" data-year="{yr}" hidden>\n'
                f'            <div class="pastfilms-block">\n'
                f'              <div class="filmmap">\n'
                f'                <img src="assets/{yr}-films.webp?v={ASSET_VER}" '
                f'alt="{yr} Nantucket Shorts Fest films"{dims} loading="lazy">\n'
                f'{filmmap_buttons(grid, cols, rows)}\n'
                f'              </div>\n'
                f'            </div>\n'
                f'          </div>')

    panels = "\n".join(panel(*y) for y in years)

    return f"""<section class="section shorts-pastfilms">
  <div class="wrap">
    <div class="section__head" data-reveal>
      <span class="eyebrow"><span class="dot"></span>Watch Past Films</span>
    </div>
    <div class="dl-group dl-group--static" data-reveal>
      <h2 class="dl-group__title">Select a Year to Watch Short Films from that Festival</h2>
      <div class="dl-group__body">
        <div class="yearpick yearpick--toggle">
          <div class="yearpick__btns" role="group" aria-label="Past films by year">
{btns}
          </div>
          <div class="yearpick__panels">
{panels}
          </div>
        </div>
      </div>
    </div>
  </div>
</section>"""

