def video_hero_vimeo(vid, vhash, fallback, alt="Nantucket New Moon Fest"):
    src = (f"https://player.vimeo.com/video/{vid}?h={vhash}"
           "&background=1&autoplay=1&loop=1&muted=1&dnt=1")
    return f"""<section class="vhero vhero--bare">
  <div class="hero__media">
    <img class="hero__fallback" src="assets/{fallback}" alt="{alt}">
    <iframe class="hero__vimeo" src="{src}" title="{alt}"
      frameborder="0" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen></iframe>
  </div>
</section>"""

