def movie_panel_html(btn_title, slug, d):
    title = d.get("title", btn_title)
    syn = "\n".join(f'            <p class="movie-synopsis">{p}</p>' for p in d["synopsis"])
    quotes = "".join(f'\n            <p class="movie-quote">{q}</p>' for q in d.get("quotes", []))
    directed = f'\n            <p class="movie-directed">{d["directed"]}</p>' if d.get("directed") else ""
    credits_block = ""
    if d.get("credits"):
        credits = "<br>".join(d["credits"])
        credits_block = ('\n            <h4 class="movie-credits-h">Credits</h4>'
                         f'\n            <p class="movie-credits">{credits}</p>')
    return f"""        <div class="movie-panel" data-movie="{slug}" hidden>
          <img class="movie-poster" src="assets/{d['poster']}?v={ASSET_VER}" alt="{title} poster">
          <div class="movie-text">
            <h3 class="movie-title">{title}</h3>
            <p class="movie-meta">{d['meta']}</p>
{syn}{quotes}{directed}{credits_block}
          </div>
        </div>"""

