def nmf_rules_items():
    """The rules as nested <li>s, rendered from NMF_RULES at build time."""
    out = []
    for item in NMF_RULES:
        if isinstance(item, tuple):
            head, subs = item
            inner = "\n".join(f"            <li>{x}</li>" for x in subs)
            out.append(f"        <li>{head}\n          <ul>\n{inner}\n"
                       f"          </ul>\n        </li>")
        else:
            out.append(f"        <li>{item}</li>")
    return "\n".join(out)


def nmf_rules_section():
    """Submission rules, shut by default behind a Learn More summary.

    Same nmf-sub collapsible as Recent News, the auction and the history: the
    eyebrow is the title and the summary is the subtitle. The list gets its own
    class rather than the Shorts Fest .criteria__list, which runs two columns
    -- several of these items are full paragraphs and would not balance.
    """
    return f"""<section class="section nmf-rules">
  <div class="wrap">
    <div class="section__head" data-reveal>
      <span class="eyebrow"><span class="dot"></span>Submission Rules &amp; Conditions</span>
    </div>
    <details class="pastsel__year dl-group nmf-sub" data-reveal>
      <summary>Learn More</summary>
      <div class="dl-group__body">
        <p class="nmf-rules__submit">To submit your film, please <a href="{NMF_SUBMIT_URL}" target="_blank" rel="noopener">click here</a></p>
        <ul class="nmf-rules__list">
{nmf_rules_items()}
        </ul>
      </div>
    </details>
  </div>
</section>"""

