# How each link label reads when a screen reader announces it with the
# business name, since "Info at ..." would not.
LINK_PREPOSITION = {"Shop": "at", "Info": "about", "Contact": ""}

def auction_partner_rows():
    """One row per partner: name, what they sell, and a link out to them.

    A partner may carry a fourth field to override the "Shop" link text, for
    one whose page is somewhere to read about them rather than to buy."""
    rows = []
    for partner in AUCTION_PARTNERS:
        name, what, url = partner[:3]
        label = partner[3] if len(partner) > 3 else "Shop"
        if not url:
            continue
        prep = LINK_PREPOSITION[label]
        spoken = f"{prep} {name}" if prep else name
        rows.append(
            f'''<li class="auction-partners__row">
            <span class="auction-partners__name">{name}</span>
            <span class="auction-partners__what">{what}</span>
            <a class="auction-partners__shop" href="{url}" target="_blank" rel="noopener">{label}<span class="sr-only"> {spoken}</span></a>
          </li>''')
    return "\n          ".join(rows)

def nmf_auction_section():
    """The auction note, collapsible, opening onto the partner list.

    Uses the same nmf-sub collapsible as Recent News and The History of New
    Moon Fest: the caret is the only cue, and the borders those accordion rows
    normally carry are suppressed because this one stands alone."""
    return f"""<section class="section nmf-auction">
  <div class="wrap">
    <div class="section__head" data-reveal>
      <span class="eyebrow"><span class="dot"></span>New Moon Fest Auction</span>
    </div>
    <details class="pastsel__year dl-group nmf-sub" data-reveal>
      <summary>To learn about the auction items, click here.</summary>
      <div class="dl-group__body">
        <p class="auction-note">This auction is a curated collection of one-of-a-kind deals from all over Nantucket. The 2026 auction may be closed, but you can see the items that sold (<a href="{AUCTION_URL}" target="_blank" rel="noopener">click here</a>) or buy the same items by visiting the websites of the auction partners on the following list.</p>
        <ul class="auction-partners">
          {auction_partner_rows()}
        </ul>
      </div>
    </details>
  </div>
</section>"""

def nmf_awards_section():
    """Winner graphics one year at a time, shaped like the Shorts Fest awards:
    eyebrow, heading, then year buttons running oldest to newest. These were
    three separate accordions until 2026-10-18, all expandable at once.

    The open year's graphic loads normally; the rest are lazy, and every one
    carries its real pixel size so a hidden panel reserves the right height
    instead of collapsing to nothing."""
    years = sorted(NMF_AWARDS)
    btns = "\n".join(
        f'        <button type="button" class="year-btn'
        f'{" is-active" if yr == NMF_AWARDS_OPEN else ""}" data-year="{yr}" '
        f'aria-pressed="{"true" if yr == NMF_AWARDS_OPEN else "false"}">{yr}</button>'
        for yr in years)

    def panel(yr):
        graphic = NMF_AWARDS[yr]
        size = webp_size(os.path.join(OUT, "assets", graphic))
        dims = f' width="{size[0]}" height="{size[1]}"' if size else ""
        open_ = yr == NMF_AWARDS_OPEN
        hidden = "" if open_ else " hidden"
        lazy = "" if open_ else ' loading="lazy"'
        return (f'        <div class="year-panel" data-year="{yr}"{hidden}>\n'
                f'          <div class="awards-panel">\n'
                f'            <img class="awards-img" src="assets/{graphic}?v={ASSET_VER}" '
                f'alt="Congratulations to the {yr} New Moon Fest winners"{dims}{lazy}>\n'
                f'            <p class="awards-text">{NMF_AWARDS_TEXT}</p>\n'
                f'          </div>\n'
                f'        </div>')

    panels = "\n".join(panel(yr) for yr in years)
    return f"""<section class="section nmf-awards">
  <div class="wrap">
    <div class="section__head" data-reveal>
      <span class="eyebrow"><span class="dot"></span>Awards</span>
      <h2>Congratulations to the New&nbsp;Moon&nbsp;Fest winners!</h2>
    </div>
    <div class="yearpick" data-reveal>
      <div class="yearpick__btns" role="group" aria-label="New Moon Fest winners by year">
{btns}
      </div>
      <div class="yearpick__panels">
{panels}
      </div>
    </div>
  </div>
</section>"""

NMF_SELECTIONS_OPEN = "2026"

def nmf_pastsel_section():
    """Official selections, one year at a time.

    Each year was its own <details> until 2026-10-18. They are now panels of a
    year picker, which is why initMoviePicker() scopes on .pastsel__movies and
    the panels beside it rather than on the old .pastsel__year wrapper.

    The newest year opens on load. That is also why this picker is not marked
    --toggle: with a year already showing, letting a click collapse it to
    nothing would read as the section having lost its contents."""
    years = [("2024", NMF_2024), ("2025", NMF_2025), ("2026", NMF_2026)]

    btns = "\n".join(
        f'        <button type="button" class="year-btn'
        f'{" is-active" if yr == NMF_SELECTIONS_OPEN else ""}" data-year="{yr}" '
        f'aria-pressed="{"true" if yr == NMF_SELECTIONS_OPEN else "false"}">{yr}</button>'
        for yr, _ in years)

    def panel(yr, movies):
        if not movies:
            body = '          <p class="dl-empty">Films for this year are coming soon.</p>'
        else:
            film_btns = "\n".join(
                f'            <button class="movie-btn" type="button" '
                f'data-movie="{slug}">{title}</button>'
                for title, slug, _ in movies)
            film_panels = "\n".join(
                movie_panel_html(title, slug, d) for title, slug, d in movies if d)
            body = (f'          <div class="pastsel__movies">\n{film_btns}\n'
                    f'          </div>\n'
                    f'          <div class="pastsel__panels">\n{film_panels}\n'
                    f'          </div>')
        hidden = "" if yr == NMF_SELECTIONS_OPEN else " hidden"
        return (f'        <div class="year-panel" data-year="{yr}"{hidden}>\n'
                f'{body}\n'
                f'        </div>')

    panels = "\n".join(panel(yr, m) for yr, m in years)
    return f"""<section class="section pastsel">
  <div class="wrap">
    <div class="section__head" data-reveal>
      <span class="eyebrow"><span class="dot"></span>Official Film Selections</span>
      <h2>Click below to Learn about the Films</h2>
    </div>
    <div class="yearpick" data-reveal>
      <div class="yearpick__btns" role="group" aria-label="Official selections by year">
{btns}
      </div>
      <div class="yearpick__panels">
{panels}
      </div>
    </div>
  </div>
</section>"""

