# Dates are held as ISO, whole or partial -- "2015", "2015-10" or "2015-10-31".
# ISO sorts correctly as plain text, so the column needs no date parsing in the
# browser, and a partial date is honest about what is actually known.
_MON = ["Jan.", "Feb.", "Mar.", "Apr.", "May", "Jun.",
        "Jul.", "Aug.", "Sep.", "Oct.", "Nov.", "Dec."]

def show_date(iso):
    """-> (sort key, what the cell shows). An unknown date shows a dash."""
    if not iso:
        return "", "&mdash;"
    p = iso.split("-")
    if len(p) == 1:
        return iso, p[0]
    if len(p) == 2:
        return iso, f"{_MON[int(p[1]) - 1]} {p[0]}"
    return iso, f"{_MON[int(p[1]) - 1]} {int(p[2])}, {p[0]}"

def show_slug(name):
    return re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-")

def show_sort_key(name):
    """Alphabetise on the first word that carries meaning, so "The Lizza Show"
    files under L the way a library catalogue would. Used both for the row
    order and for the Show Name column's data-sort, so the two never
    disagree."""
    return re.sub(r"^(?:the|a|an)\s+", "", name.lower())

def show_episode_panel(name):
    """One show's episodes, behind year buttons where those earn their place.

    The cards are the meeting cards used across the site with both extra
    controls off: these are episodes, so there is no agenda and no highlight.

    With one or two years the buttons do no work, so the episodes are listed
    straight out. That list must not be a .year-panel: clearPicks() hides every
    .year-panel in a show when the show is collapsed, which would leave a
    button-less show empty the second time it was opened.
    """
    years = PAST_SHOW_VIDEOS.get(name) or {}
    if not years:
        return ""

    def cards_for(eps):
        last = len(eps) - 1
        return "\n".join(civic_card(v, t, rule=(i != last), agenda_btn=False, desc=d)
                          for i, (v, t, d) in enumerate(eps))

    if len(years) <= 2:
        flat = [ep for y in sorted(years) for ep in years[y]]
        return ('          <div class="show-episodes">\n%s\n'
                '          </div>' % cards_for(flat))

    btns = "\n".join(
        f'              <button type="button" class="year-btn" data-year="{y}" '
        f'aria-pressed="false">{y}</button>' for y in sorted(years))
    panels = []
    for y in sorted(years):
        panels.append('              <div class="year-panel" data-year="%s" hidden>\n%s\n'
                      '              </div>' % (y, cards_for(years[y])))
    inner = "\n".join(panels)
    return ('          <div class="yearpick yearpick--toggle">\n'
            '            <div class="yearpick__btns" role="group" aria-label="%s by year">\n'
            '%s\n'
            '            </div>\n'
            '            <div class="yearpick__panels">\n'
            '%s\n'
            '            </div>\n'
            '          </div>' % (name, btns, inner))

def past_shows_table(shows):
    if not shows:
        return ""
    rows = []
    for n, g, d, a, b in sorted(shows, key=lambda row: show_sort_key(row[0])):
        ka, va = show_date(a)
        kb, vb = show_date(b)
        panel = show_episode_panel(n)
        # A show with episodes gets a button; one without stays plain text,
        # since there would be nothing for a click to open.
        cell = (f'<button type="button" class="shows__name" aria-expanded="false">{n}</button>'
                if panel else n)
        rows.append(f'          <tr><th scope="row" data-sort="{show_sort_key(n)}">{cell}</th>'
                    f'<td data-sort="{g.lower()}">{g}</td>'
                    f'<td>{d}</td><td data-sort="{ka}">{va}</td>'
                    f'<td data-sort="{kb}">{vb}</td></tr>')
        if panel:
            # The episodes sit in a row of their own, directly under the show,
            # so the rest of the table carries on below them.
            rows.append('          <tr class="shows__panel" hidden><td colspan="5">\n'
                        '%s\n          </td></tr>' % panel)

    def head(label, sortable=True):
        if not sortable:
            return f'<th scope="col">{label}</th>'
        return (f'<th scope="col" aria-sort="none">'
                f'<button type="button" class="shows__sort">{label}</button></th>')

    body = "\n".join(rows)
    return ('<section class="section shows">\n'
            '  <div class="wrap" data-reveal>\n'
            '    <p class="shows__hint">Click the column headers to sort the rows.</p>\n'
            '    <div class="shows__scroll">\n'
            '      <table class="shows__table">\n'
            '        <thead>\n'
            '          <tr>%s%s%s\n            %s%s</tr>\n'
            '        </thead>\n'
            '        <tbody>\n'
            '%s\n'
            '        </tbody>\n'
            '      </table>\n'
            '    </div>\n'
            '  </div>\n'
            '</section>' % (head("Show Name"), head("Topic"), head("Description", False),
                            head("First<br>Ep. Date"), head("Last<br>Ep. Date"), body))

