def atheneum_groups():
    """Turn the ID lists into the (vid, title, desc) tuples the cards expect."""
    groups = []
    for label, short, years in ATHENEUM_SERIES:
        by_year = {}
        for yr, ids in years.items():
            cards = []
            for i, v in enumerate(ids, 1):
                title, desc = ATHENEUM_TITLES.get(v, (None, ""))
                if title is None:
                    title = f"{short} {yr}"
                    if len(ids) > 1:
                        title += f" ({i} of {len(ids)})"
                cards.append((v, title, desc))
            by_year[yr] = cards
        groups.append((label, by_year))
    return groups

def atheneum_series(short):
    """One series from atheneum_groups(), found by its short name.

    The Summer Forum is co-sponsored by the Atheneum, the Civic League and NCTV,
    so it belongs on two partner pages. Both read it from here rather than
    keeping separate lists: add a year to ATHENEUM_SERIES and both pages get it.
    """
    for (_, name, _), (_, by_year) in zip(ATHENEUM_SERIES, atheneum_groups()):
        if name == short:
            return by_year
    raise KeyError(short)


