def school_page():
    body = "\n".join([
        channel_hero("school", chero_logo("school-nps.webp", "Nantucket Public Schools"),
                     "NCTV School Videos", ""),
        mission_section(NPS_MISSION, "their", "https://www.npsk.org/"),
        programs_section([("School Committee", NPS_COMMITTEE)], heading=None,
                         newest_first=True, panel_note=("School Yr 24-25", AI_NOTE),
                         after=('For Nantucket Civic TV, '
                                '<a href="videos-civic.html">click here</a>.')),

        org_banner("nhs", "school-nhs.webp", "Nantucket High School", "Nantucket High School"),
        mission_section(NHS_MISSION, "the school&rsquo;s", "https://nhs.npsk.org/"),
        programs_section([("Whaler Word",   WHALER_WORD),
                          ("Graduation",    NHS_GRADUATION),
                          ("Senior Awards", NHS_SENIOR_AWARDS)], heading=None,
                         after=('For Sports, <a href="videos-sports-connection.html">Click '
                                'Here</a> for Nantucket Sports Connection')),

        org_banner("cps", "school-cps.webp", "Cyrus Peirce Middle School",
                   "Cyrus Peirce Middle School"),
        mission_section(CPS_MISSION, "the school&rsquo;s", "https://cps.npsk.org/"),
        programs_section([("The CPS Pulse",        CPS_PULSE),
                          ("8th Grade Promotion",  CPS_PROMOTION)], heading=None),
    ])
    return shell("videos-school.html",
                 "NCTV School Videos — Nantucket Community Television", body)


files["videos-school.html"] = school_page()

