# ----------------------------------------------------------------------
# 13) SEARCH
#
# The site is static, so search runs in the browser. This reads the finished
# pages and writes `search-index.js`, a plain <script> (not JSON fetched over
# the network) so the search page still works from a file:// preview. Only
# search.html loads it; no other page pays for it.
#
# The index is read from the generated HTML rather than from the dozens of
# data structures above, so whatever is actually on a page is what is
# searchable -- add a video anywhere and it is indexed on the next build.
SEARCH_CARD  = re.compile(r'<article class="watch-episode"[^>]*>(.*?)</article>', re.S)
SEARCH_TITLE = re.compile(r'class="watch-episode__title">(.*?)</h3>', re.S)
SEARCH_DESC  = re.compile(r'class="watch-episode__desc[^"]*">(.*?)</p>', re.S)
SEARCH_VID   = re.compile(r'href="https://youtu\.be/([\w-]{6,})"')
SEARCH_THUMB = re.compile(r'img\.youtube\.com/vi/([\w-]{6,})/')
SEARCH_PAGE  = re.compile(r'<title>(.*?)</title>', re.S)
_TAGS = re.compile(r"<[^>]+>")
_WS   = re.compile(r"\s+")

def plain(fragment):
    """Markup to the words a reader actually sees."""
    import html as _html
    return _WS.sub(" ", _html.unescape(_TAGS.sub(" ", fragment))).strip()

# A page title puts the site's own name on whichever side of the dash reads
# better -- "NCTV Videos — Nantucket Atheneum" but "Nantucket Civic TV — NCTV"
# -- so taking the first half would file half the archive under "NCTV Videos".
# Drop whichever halves are the site's name and keep the distinctive part.
SITE_NAMES = {"nctv", "nctv videos", "nantucket community television"}

def page_label(title):
    parts = [part.strip() for part in title.split("—")]
    kept = [part for part in parts if part and part.lower() not in SITE_NAMES]
    return " — ".join(kept) if kept else title.strip()

def build_search_index(pages):
    """(javascript, content hash) for every video card on the site.

    Records are arrays, not objects, and the page names are interned, because
    the key names repeat 5,000 times otherwise -- it saves about a third of
    the file. Order is [youtube id, title, description, page index]."""
    import hashlib, json
    page_list, page_ix, rows = [], {}, []
    for name in sorted(pages):
        html_text = pages[name]
        if '<article class="watch-episode"' not in html_text:
            continue
        label = page_label(plain(SEARCH_PAGE.search(html_text).group(1)))
        for card in SEARCH_CARD.finditer(html_text):
            body = card.group(1)
            title = SEARCH_TITLE.search(body)
            if not title:
                continue
            vid = SEARCH_VID.search(body) or SEARCH_THUMB.search(body)
            if name not in page_ix:
                page_ix[name] = len(page_list)
                page_list.append([name, label])
            rows.append([vid.group(1) if vid else "",
                         plain(title.group(1)),
                         " ".join(plain(d) for d in SEARCH_DESC.findall(body)),
                         page_ix[name]])
    blob = json.dumps({"pages": page_list, "videos": rows},
                      ensure_ascii=False, separators=(",", ":"))
    js = ("/* Generated by build.py -- do not edit. Every video card on the\n"
          "   site, as [youtube id, title, description, page index]. */\n"
          "window.NCTV_SEARCH = " + blob + ";\n")
    return js, hashlib.sha1(blob.encode("utf-8")).hexdigest()[:10]

def search_page(index_hash):
    body = f"""{page_header("Search", "Search the video archive.",
      "Every video NCTV has published, searched by title and by description.")}

<main class="section search-page">
  <div class="wrap">
    <form class="searchbox" role="search" action="search.html" data-search-form>
      <input class="searchbox__input" type="search" name="q" placeholder="Search videos&hellip;"
             aria-label="Search videos" autocomplete="off" spellcheck="false" data-search-input>
      <button class="searchbox__btn" type="submit">Search</button>
    </form>
    <p class="search-status" data-search-status role="status"></p>
    <div data-search-results></div>
  </div>
</main>"""
    return shell("search.html", "Search — Nantucket Community Television", body,
                 scripts=f'\n<script src="search-index.js?v={index_hash}"></script>'
                         f'\n<script src="search.js?v={ASSET_VER}"></script>')

# Built last: the index is read from the finished pages, and the page needs
# the index's hash so a changed index busts its own cache.
SEARCH_INDEX_JS, SEARCH_INDEX_HASH = build_search_index(files)
files["search.html"] = search_page(SEARCH_INDEX_HASH)

# remove any stale page that's no longer part of the site
for _stale in ["videos-other-programs.html", "partner-town.html", "partner-public-schools.html"]:
    _p=os.path.join(OUT,_stale)
    if os.path.exists(_p): os.remove(_p)

for name, html in files.items():
    with open(os.path.join(OUT, name), "w") as f:
        f.write(html)
# Not a page, so it is written here rather than through `files` and is not
# counted below.
with open(os.path.join(OUT, "search-index.js"), "w") as f:
    f.write(SEARCH_INDEX_JS)
print("Wrote", len(files), "pages:")
for n in sorted(files): print("  ", n)
